tool_sources.check_leave_balance:
{
  "name": "check_leave_balance",
  "title": "Check leave balance",
  "category": "HR",
  "description": "The signed-in employee's leave balance by type (CL casual, EL earned, SL sick) and any open comp-offs, with their employee code. Leave employee_name empty for yourself.",
  "writes": false,
  "version": "1.0",
  "services": [
    "lv_emp_get",
    "lv_bal_get"
  ],
  "input_schema": {
    "type": "object",
    "properties": {
      "employee_name": {
        "type": "string",
        "description": "only to look someone else up by name; blank = yourself"
      }
    },
    "required": []
  },
  "output_schema": {
    "type": "object",
    "properties": {
      "ok": {
        "type": "boolean"
      },
      "employee_code": {
        "type": "string"
      },
      "balances": {
        "type": "object",
        "description": "leave type -> days left"
      },
      "comp_offs_open": {
        "type": "array"
      },
      "next_step": {
        "type": "string",
        "description": "what to do next, when there is something to ask"
      }
    }
  },
  "example": {}
}

tool_sources.working_days:
{
  "name": "working_days",
  "title": "Working days",
  "category": "HR",
  "writes": false,
  "version": "1.0",
  "description": "Count the working days between two dates (inclusive) at the employee's plant: Sundays and plant holidays are not counted. Use it to turn 'Thursday and Friday' into dates and days before applying.",
  "services": [
    "lv_hol_list"
  ],
  "input_schema": {
    "type": "object",
    "properties": {
      "from_date": {
        "type": "string",
        "description": "YYYY-MM-DD"
      },
      "to_date": {
        "type": "string",
        "description": "YYYY-MM-DD"
      }
    },
    "required": [
      "from_date",
      "to_date"
    ]
  },
  "output_schema": {
    "type": "object",
    "properties": {
      "ok": {
        "type": "boolean"
      },
      "days": {
        "type": "number"
      },
      "dates": {
        "type": "array"
      },
      "holidays": {
        "type": "array"
      }
    }
  },
  "example": {
    "from_date": "2026-10-29",
    "to_date": "2026-10-30"
  }
}

tool_sources.apply_leave:
{
  "name": "apply_leave",
  "title": "Apply for leave",
  "category": "HR",
  "writes": true,
  "version": "1.0",
  "description": "Apply for leave for the signed-in employee. leave_type: CL casual, EL earned, SL sick. confirm=false previews the days, the balance, any unpaid days and who approves, and saves nothing; confirm=true applies. If the balance of the chosen type does not cover every day, Bahi holds the application unpaid and it never reaches the approver: pick a type that covers it (the preview says which).",
  "services": [
    "lv_emp_get",
    "lv_bal_get",
    "lv_hol_list",
    "lv_fetch",
    "lv_save",
    "lv_list"
  ],
  "input_schema": {
    "type": "object",
    "properties": {
      "leave_type": {
        "type": "string",
        "enum": [
          "CL",
          "EL",
          "SL"
        ],
        "description": "CL, EL or SL"
      },
      "from_date": {
        "type": "string",
        "description": "YYYY-MM-DD"
      },
      "to_date": {
        "type": "string",
        "description": "YYYY-MM-DD"
      },
      "reason": {
        "type": "string",
        "description": "in the employee's words"
      },
      "confirm": {
        "type": "boolean",
        "description": "false (default) = preview only; true = apply"
      }
    },
    "required": [
      "leave_type",
      "from_date",
      "to_date",
      "reason"
    ]
  },
  "output_schema": {
    "type": "object",
    "properties": {
      "ok": {
        "type": "boolean"
      },
      "leave_no": {
        "type": "string"
      },
      "status": {
        "type": "string",
        "description": "WAITING FOR APPROVAL, APPROVED, HELD (unpaid) ..."
      },
      "unpaid_days": {
        "type": "number"
      },
      "warning": {
        "type": "string"
      }
    }
  },
  "example": {
    "leave_type": "EL",
    "from_date": "2026-10-29",
    "to_date": "2026-10-30",
    "reason": "sister's wedding"
  }
}

tool_sources.leave_status:
{
  "name": "leave_status",
  "title": "Leave status",
  "category": "HR",
  "writes": false,
  "version": "1.0",
  "description": "The signed-in employee's leave applications with their real status in words (waiting, approved, held unpaid), days, unpaid days and approver. Give leave_no for one application.",
  "services": [
    "lv_emp_get",
    "lv_list"
  ],
  "input_schema": {
    "type": "object",
    "properties": {
      "leave_no": {
        "type": "string",
        "description": "e.g. LV/2026/00388; blank = all of mine"
      }
    },
    "required": []
  },
  "output_schema": {
    "type": "object",
    "properties": {
      "ok": {
        "type": "boolean"
      },
      "applications": {
        "type": "array"
      }
    }
  },
  "example": {}
}
